raw.css:
:root {
  --color-bg: #fffaf5;
  --color-surface: #ffffff;
  --color-text: #2b2420;
  --color-text-muted: #5a4f48;
  --color-border: #e5d9ce;
  --color-primary-dark: #6b2142;
  --color-primary-darker: #4a1730;
  --color-accent-on-dark: #f3c969;
  --font-body: Georgia, "Times New Roman", serif;
  --font-heading: "Palatino Linotype", "Book Antiqua", Georgia, serif;
  --space-xs: 0.5rem;
  --space-sm: 1rem;
  --space-md: 1.5rem;
  --space-lg: 2.5rem;
  --space-xl: 4rem;
  --radius: 0.4rem;
  --max-width: 75rem;
}

* { box-sizing: border-box; }

html { scroll-behavior: smooth; }

body {
  margin: 0;
  font-family: var(--font-body);
  background: var(--color-bg);
  color: var(--color-text);
  line-height: 1.6;
  font-size: 1rem;
}

h1, h2, h3 {
  font-family: var(--font-heading);
  color: var(--color-primary-dark);
  line-height: 1.25;
  margin-top: 0;
}

p { margin-top: 0; }

a {
  color: var(--color-primary-dark);
  text-decoration: underline;
}

a:hover { color: var(--color-primary-darker); }

a:focus-visible,
button:focus-visible,
input:focus-visible,
textarea:focus-visible {
  outline: 3px solid var(--color-primary-dark);
  outline-offset: 2px;
}

.container {
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 0 1.25rem;
  width: 100%;
}

/* Header */
header {
  background: var(--color-surface);
  border-bottom: 1px solid var(--color-border);
}

.header-inner {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: space-between;
  gap: var(--space-sm);
  padding-top: var(--space-sm);
  padding-bottom: var(--space-sm);
}

.logo {
  font-family: "Palatino Linotype", "Book Antiqua", serif;
  font-variant: small-caps;
  font-weight: 400;
  letter-spacing: 0.25em;
  font-size: clamp(1.1rem, 3vw, 1.5rem);
  color: var(--color-primary-dark);
  text-decoration: none;
  border-bottom: 1px solid var(--color-primary-dark);
  width: fit-content;
  padding-bottom: 0.15em;
}

.logo:hover { color: var(--color-primary-darker); }

nav[aria-label="Main"] {
  display: flex;
  flex-wrap: wrap;
  gap: var(--space-md);
}

nav[aria-label="Main"] a {
  text-decoration: none;
  color: var(--color-text);
  font-weight: 600;
  padding: 0.5rem 0.25rem;
}

nav[aria-label="Main"] a:hover {
  color: var(--color-primary-dark);
  text-decoration: underline;
}

/* Footer */
footer {
  background: var(--color-primary-darker);
  color: #ffffff;
  margin-top: var(--space-xl);
}

.footer-inner {
  padding: var(--space-lg) 1.25rem;
  text-align: center;
}

.footer-brand {
  font-family: var(--font-heading);
  font-variant: small-caps;
  letter-spacing: 0.2em;
  color: var(--color-accent-on-dark);
  font-size: 1.1rem;
  margin-bottom: var(--space-xs);
}

footer p {
  color: #ffffff;
  margin: 0.25rem 0;
}

/* Buttons */
.button {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-height: 44px;
  padding: 0.6rem 1.5rem;
  background: var(--color-primary-dark);
  color: #ffffff;
  border: none;
  border-radius: var(--radius);
  font-size: 1rem;
  font-weight: 700;
  text-decoration: none;
  cursor: pointer;
}

.button:hover {
  background: var(--color-primary-darker);
}

/* Cards */
.card {
  background: var(--color-surface);
  border: 1px solid var(--color-border);
  border-radius: var(--radius);
  padding: var(--space-md);
  display: flex;
  flex-direction: column;
  gap: var(--space-xs);
}

.card h3 { font-size: 1.25rem; }

.card .meta {
  color: var(--color-text-muted);
  font-size: 0.875rem;
  margin-bottom: var(--space-xs);
}

/* Grid helper */
.grid {
  display: grid;
  gap: var(--space-md);
  grid-template-columns: 1fr;
}

/* Forms */
form {
  display: flex;
  flex-direction: column;
  gap: var(--space-sm);
  max-width: 30rem;
}

label {
  font-weight: 700;
  display: block;
  margin-bottom: 0.25rem;
}

input[type="text"],
input[type="email"],
textarea {
  width: 100%;
  min-height: 44px;
  padding: 0.6rem 0.75rem;
  border: 1px solid var(--color-border);
  border-radius: var(--radius);
  font-size: 1rem;
  font-family: inherit;
  background: var(--color-surface);
  color: var(--color-text);
}

textarea { min-height: 7rem; resize: vertical; }

input:focus,
textarea:focus {
  border-color: var(--color-primary-dark);
}

/* Sections */
section {
  padding: var(--space-lg) 0;
}

.hero {
  text-align: center;
  padding: var(--space-xl) 0;
}

.hero p {
  max-width: 40rem;
  margin: var(--space-sm) auto 0;
  color: var(--color-text-muted);
  font-size: 1.1rem;
}

/* Mobile breakpoint */
@media (max-width: 600px) {
  .header-inner {
    flex-direction: column;
    align-items: flex-start;
  }

  nav[aria-label="Main"] {
    gap: var(--space-sm);
  }

  .hero {
    padding: var(--space-lg) 0;
  }

  h1 { font-size: 1.6rem; }
  h2 { font-size: 1.3rem; }
}

/* Desktop breakpoint */
@media (min-width: 601px) {
  .grid {
    grid-template-columns: repeat(2, 1fr);
  }

  .grid.posts-grid {
    grid-template-columns: repeat(3, 1fr);
  }

  .hero h1 { font-size: 2.5rem; }
}

@media (prefers-reduced-motion: reduce) {
  html { scroll-behavior: auto; }
  * { animation: none !important; transition: none !important; }
}

